            new Quote { Id = "https://en.wikiquote.org/wiki/Jack_Kerouac", Text = "I want to work in revelations, not just spin silly tales for money. I want to fish as deep down as possible into my own subconscious in the belief that once that far down, everyone will understand because they are the same that far down.", Author = "Jack Kerouac" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jack_Kerouac", Text = "I hope it is true that a man can die and yet not only live in others but give them life, and not only life but that great consciousness of life.", Author = "Jack Kerouac" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jack_Kerouac", Text = "Write in recollection and amazement for yourself", Author = "Jack Kerouac" },
