            new Quote { Id = "https://en.wikiquote.org/wiki/Jack_Kerouac", Text = "Who knows, my God, but that the universe is not one vast sea of compassion actually, the veritable holy honey, beneath all this show of personality and cruelty?", Author = "Jack Kerouac" },
